(window.SITE_LANG_DATA = window.SITE_LANG_DATA || {})["sw"] = {"ui":{"skip":"Ruka hadi maudhui","back":"← Rudi kwenye AI-gile","lang.button":"Lugha: {name}","lang.dialog":"Chagua lugha","lang.search":"Tafuta lugha","lang.none":"Hakuna lugha inayolingana","lang.notYet":"{name} haijatafsiriwa bado","theme.aria":"Badilisha kati ya mandhari angavu na meusi","theme.toLight":"Badili kwenda mandhari angavu","theme.toDark":"Badili kwenda mandhari meusi","index.title":"AI-gile: timu yako ya AI ya wasanidi, kwenye ubao mmoja","index.description":"AI-gile ni ubao wa kanban kwa timu za AI zinazoandika msimbo. Hufanya kazi wakati umelala; wewe unapata rundo moja fupi la mambo ya kuamua, kujaribu na kukubali.","hero.logoAlt":"Ikoni ya ubao wa AI-gile","hero.h1.html":"Timu yako ya AI ya wasanidi, kwenye ubao&nbsp;mmoja.","hero.alpha":"🐣 Pre-alpha iliyofungwa","hero.alphaTitle":"Bado mapema na haijakamilika: asante kwa kujaribu!","hero.lede":"Wanajenga wakati umelala. Unaamka kukuta rundo moja fupi: maswali machache, mambo machache ya kujaribu, almasi moja au mbili za zambarau. Bofya, kubali, rudi kwenye kahawa yako.","dl.windows":"Programu ya Windows","dl.browser":"Iendeshe kwenye kivinjari","dl.soon":"Inakuja hivi karibuni","dl.notify":"🔔 Niambie itakapofunguliwa","dl.notifySmall":"Alpha au beta","hero.secondary":"Agile, lakini timu haihitaji kahawa ya stand-up kamwe. (Hufanya stand-up hata hivyo.)","pitch.h2":"AI-gile kwa maneno mengi kadri upendavyo","pitch.lede":"Chagua urefu, kuanzia neno moja hadi 144. Kila urefu ni maelezo yake yenyewe, yaliyoandikwa kwa ukubwa huo. Buruta kitelezi au tumia vitufe vya mishale.","pitch.rangeLabel":"Urefu kwa maneno","pitch.dice":"🎲 toleo jingine","pitch.words.one":"neno {n}","pitch.words.other":"maneno {n}","pitch.letters.one":"herufi {n}","pitch.letters.other":"herufi {n}","pitch.chars.one":"kibambo {n}","pitch.chars.other":"vibambo {n}","count.line.html.one":"kadi {n} kwenye ubao sasa hivi","count.line.html.other":"kadi {n} kwenye ubao sasa hivi","features.aria":"Inafanya nini","f.pile.h":"Rundo moja kwa ajili yako","f.pile.html":"<b>Kwako</b> hushikilia kila kitu kinachokusubiri, kwenye kila mradi: maswali, mambo ya kujaribu, kazi ambazo binadamu pekee anaweza kuzifanya. Foleni yako inaonyesha kinachofuata na kitachukua muda gani.","f.sleep.h":"Timu zinazofanya kazi ukiwa umelala","f.sleep.p":"Kila mradi una kiongozi na timu ya mawakala wa AI. Toa maoni kwenye kadi na timu inaamka, inafanya kazi, na kuirudisha pamoja na hatua ambazo binadamu aliyechoka anaweza kuzifuata.","f.tester.h":"Mjaribu wa AI hukagua kwanza","f.tester.p":"Kabla ya chochote kukufikia, mjaribu hufuata hatua kwenye nakala ya programu na kuonyesha alichokiona, pamoja na picha ya skrini. Pitia zile zilizofaulu na ukubali kwa bofya moja.","f.proof.h":"Ushahidi, si ahadi","f.proof.p":"Kila makabidhiano yanaonyesha kilichobadilika: faili, tofauti, picha za skrini. Huhitaji kufungua kila programu kuona kama imekamilika.","f.chat.h":"Piga gumzo na viongozi wako","f.chat.p":"Safu kama ya Discord: ikoni moja kwa kila mradi, almasi za zambarau kwa kinachokuhitaji. Mwandikie kiongozi wazo; analigeuza kuwa kadi na mpango, pamoja na kitufe cha ✅ Anza.","f.tidy.h":"Hujipanga yenyewe","f.tidy.p":"Kadi zinazohusiana huunganishwa kuwa moja, vichwa vilivyochanganyika hurekebishwa, na ukaguzi wa tokeni huweka msimbo mwepesi. Mambo machache ya kubadilisha kati yake, machache ya kufikiria.","f.private.h":"Yako, kwenye kompyuta yako","f.private.li1":"Ubao huendeshwa kwenye kompyuta yako mwenyewe na hukujibu wewe tu.","f.private.li2":"Ujumbe wa faragha kati ya watu umesimbwa kutoka mwanzo hadi mwisho.","f.private.li3":"Hakuna akaunti, hakuna vifuatiliaji, hakuna vidakuzi.","f.lang.h":"Kwa lugha yako","f.lang.p":"Zaidi ya lugha 120, kuanzia Kiholanzi, Kiwelisi na Kijapani hadi maharamia, Yoda na Kiklingoni, na kubadili haraka kurudi Kiingereza kwa maneno ya wasanidi.","tl.aria":"Ratiba ya matukio kuanzia mazungumzo ya kwanza hadi mpango wa mbele","tl.h2":"Kuanzia gumzo la kwanza hadi yajayo","tl.lede":"Tarehe na saa halisi, katika saa za eneo lako. Baada ya leo ni mpango, bila tarehe za ahadi.","tl.today":"Leo","tl.planned":"imepangwa","tl.cards.one":"kadi {n}","tl.cards.other":"kadi {n}","join.h2":"Jiunge nasi","join.lede":"AI-gile inajengwa na binadamu mmoja mdogo na mawakala wengi wenye subira. Kwa sasa ni ya faragha, kwenye alpha iliyofungwa na marafiki. Ungependa kujaribu itakapofunguliwa?","join.btn":"Onyesha nia","join.small":"Tutakutumia barua pepe, hakuna kingine","footer.tag":"AI-gile. Hakuna vifuatiliaji, hakuna vidakuzi, hakuna kahawa ya stand-up.","footer.licence":"Leseni ya biashara","footer.status":"Hali","form.sending":"Inatuma…","form.failed":"Haikufanikiwa: jaribu tena baadaye.","form.offline":"Imeshindwa kufikia AI-gile: jaribu tena baadaye.","interest.title":"AI-gile: niambie alpha itakapofunguliwa","interest.description":"Acha barua pepe yako ujue alpha au beta iliyofungwa ya AI-gile itakapofunguliwa.","interest.h1":"🔔 Niambie itakapofunguliwa","interest.lede":"AI-gile iko kwenye pre-alpha iliyofungwa. Acha barua pepe yako nasi tutakuandikia mara moja, kukiwa na nafasi kwako.","interest.email":"Barua pepe yako","interest.which":"Jaribio lipi?","interest.alpha":"Alpha iliyofungwa: mapema, changa, mabadiliko mengi","interest.beta":"Beta: thabiti zaidi, baadaye","interest.both":"Lolote, lile litakalokuja kwanza","interest.submit":"Niweke kwenye orodha","interest.thanks":"Asante! Uko kwenye orodha.","interest.kept":"Ni barua pepe yako na jaribio ulilochagua tu vinavyohifadhiwa, kwa orodha hii pekee. Hakuna jarida, hakuna vifuatiliaji.","licence.title":"AI-gile: leseni ya biashara","licence.description":"Unatumia AI-gile kwenye biashara yako? Omba leseni ya biashara ya bure.","licence.h1":"📜 Leseni ya biashara","licence.lede":"Unatumia AI-gile kazini? Tuambie wewe ni nani na unafanya nini. Ikifanya mema, leseni ni bure.","licence.company":"Kampuni","licence.website":"Tovuti","licence.what":"Unachofanya","licence.how":"Inavyosaidia dunia","licence.email":"Barua pepe","licence.submit":"Omba","licence.thanks":"Asante! Tutajibu kwa barua pepe.","status.title":"Hali ya AI-gile","status.h1":"Hali ya AI-gile","status.quiet":"Kimya kabisa","status.checking":"Inakagua…","status.offline":"Huduma ya hali haipatikani sasa hivi (inajaribu tena)","status.updated":"imesasishwa {ago}","status.justNow":"sasa hivi","status.min":"dakika {n} zilizopita","status.hours":"saa {n} zilizopita","status.days":"siku {n} zilizopita","live.h2":"Itazame ikijengwa, moja kwa moja","live.caption":"Kila kadi imefichwa: unaona umbo la kazi, si maneno.","live.watching.one":"moja kwa moja: {n} wanatazama","live.watching.other":"moja kwa moja: {n} wanatazama","live.offline":"Ubao wa moja kwa moja unapumzika kidogo. Rudi tena hivi karibuni.","live.cols":"Backlog|Za kufanya|Zinaendelea|Timu inakagua|Zako za kujaribu|Kwa timu|Zimekamilika"},"lines":{"unit":"words","sizes":[{"n":1,"texts":["Kanban.","Roboti.","Kukabidhi."]},{"n":2,"texts":["Kanban, kiotomatiki.","Mawakala, wamepangika.","Mawazo, yamejengwa."]},{"n":3,"texts":["Kanban ya roboti.","Mawazo yanakuwa vipengele.","Kanban ya mawakala, bure."]},{"n":5,"texts":["Ubao wa kanban unaoendeshwa na mawakala.","Wewe andika kadi. Mawakala wanajenga.","Bure, binafsi, imejaribiwa, kidogo kichekesho."]},{"n":8,"texts":["Ubao wa bure wa kanban wenye mawakala wa AI.","Andika wazo. Mawakala wanalijenga. Wewe unakubali.","Agile kwa binadamu mmoja na roboti wengi wenye subira."]},{"n":13,"texts":["Ubao wa kanban kwenye kompyuta yako ambapo mawakala wa AI huchukua kadi na kujenga.","Andika wazo. Timu ya mawakala inalijenga. Mjaribu analikagua, kisha wewe unaamua.","Bure, bila akaunti wala vifuatiliaji: ubao, roboti kadhaa, na wewe ukiwa kiongozi."]},{"n":21,"texts":["AI-gile ni ubao wa kanban wa kufanya kazi na mawakala wa AI wanaoandika msimbo. Wao huchukua kadi; wewe unazijaribu na kuzikubali.","Kila mradi unapata kiongozi na timu ya mawakala wa AI. Toa maoni kwenye kadi yoyote na timu inaanza kazi.","Ubao wa majukumu wa bure na binafsi unaoendeshwa kwenye kompyuta yako mwenyewe. Wafanyakazi ni roboti. Anayesema ndiyo ni wewe."]},{"n":34,"texts":["Unaweka mawazo kwenye ubao. Timu ya mawakala wa AI inayageuza kuwa vipengele vinavyofanya kazi, inavijaribu, na kukurudishia pamoja na hatua za kujaribu. Hakuna kinachohesabiwa kuwa kimekamilika hadi useme.","AI-gile ni ubao wa kanban uliotengenezwa nyumbani ambao Rich aliujenga kwa msaada mkubwa wa mawakala anaowasimamia sasa. Ni wa bure, huendeshwa kwenye kompyuta yako, na hushirikiwa na marafiki, hauuzwi.","Fikiria ubao wa kawaida wa kanban, wenye safu kutoka Backlog hadi Zimekamilika, isipokuwa kadi zinachukuliwa na mawakala wa AI. Wanaripoti maendeleo, wanauliza wanapokwama, na daima wanasubiri kidole chako gumba juu."]},{"n":55,"texts":["AI-gile ni ubao wa kanban ambapo timu inaundwa na mawakala wa AI. Kila mradi una kiongozi anayepanga kazi na wasaidizi wanaojenga. Kipengele kikiwa tayari, mjaribu wa AI analijaribu na kupiga picha ya skrini, kisha kinatua kwenye rundo lako. Kikubali, au toa maoni nao wakifanyie kazi upya.","Ilianza kama njia ya mtu mmoja ya kufuatilia vikao vingi vya AI vya kuandika msimbo kwa wakati mmoja, kisha ikakua kuwa ubao kamili. Inaendeshwa kwenye kompyuta yako, haihitaji akaunti, na haina vifuatiliaji. Ni ya bure kwa marafiki na wadadisi. Pia haijakamilika, kwa hiyo tarajia kasoro na mshangao mara moja moja.","Hili hapa toleo la ukweli. Bado ni wewe unayehitaji kuwa na mawazo, na bado ni wewe unayekagua matokeo. AI-gile hufanya kila kitu kilicho katikati: huweka kadi kwa mpangilio, huamsha wakala sahihi unapotoa maoni, huonyesha hasa kilichobadilika, na hukusanya yote kwenye rundo moja fupi kwa ajili yako."]},{"n":89,"texts":["AI-gile ni ubao wa kanban wa bure unaouendesha kwenye kompyuta yako mwenyewe. Badala ya watu, kila mradi una timu ya mawakala wa AI: kiongozi anayegeuza mawazo yako kuwa kadi na mpango, na wasaidizi wanaochukua kadi kwa mpangilio wa kipaumbele. Kitu kikijengwa, mjaribu wa AI hufuata hatua za majaribio na kukuonyesha alichokiona. Kisha kinasubiri kwenye rundo moja liitwalo Kwako. Unakikubali, au unatoa maoni na timu inajaribu tena. Hakuna kitu kinachofika Zimekamilika bila wewe.","Kuna mambo kadhaa ambayo huenda hukuyatarajia. Mlinzi wa usiku hujaza safu ya Za kufanya ukiwa umelala, akichagua kadi zisizohitaji jibu kutoka kwako. Kihesabu cha tokeni kinaonyesha mawakala wametumia kiasi gani leo na wiki hii, na No Token Mode huwaambia waache kutumia. Unaweza kuwatumia marafiki ujumbe, na ujumbe wa faragha umesimbwa kutoka mwanzo hadi mwisho. Ubao huzungumza takriban lugha 120, zikiwemo Kiholanzi, Kiflemi, maharamia na Kiklingoni. Hakuna hata kimoja kinachogharimu senti, na hakuna anayejaribu kukuuzia chochote pia.","AI-gile ni mradi mdogo, binafsi, si kampuni. Rich alitaka kutunza miradi kadhaa ya AI ya kuandika msimbo bila kufungua kila programu kuangalia hali, kwa hiyo yeye na mawakala wakajenga ubao kwa ajili hiyo, kisha wakautumia ubao huo kujenga sehemu iliyobaki yake. Uko kwenye pre-alpha iliyofungwa, yaani unafanya kazi, kwa kiasi kikubwa, kwa marafiki wachache. Hakuna ukurasa wa bei, hakuna jarida na hakuna mpango wa kukua. Ukionekana kukufaa, unaweza kuomba kujaribu utakapofunguliwa zaidi kidogo."]},{"n":144,"texts":["AI-gile ni ubao wa kanban kwa binadamu mmoja na mawakala wengi wa AI. Unaendeshwa kwenye kompyuta yako mwenyewe na ni wa bure kabisa. Unaongeza miradi, na kila mradi unapata kiongozi na timu ndogo. Unapiga gumzo na kiongozi, kama vile Discord, na kueleza wazo; kiongozi analigeuza kuwa kadi na mpango, kisha anasubiri ubonyeze Anza. Timu inapitia kadi kwa mpangilio wa kipaumbele, ikitumia zana rahisi ya mstari wa amri iliyotengenezwa kwa miundo ya lugha. Kabla chochote hakijakurudia, mjaribu wa AI hufuata hatua kwenye nakala ya programu na kuambatisha picha ya skrini. Kazi iliyokamilika inatua kwenye rundo lako pamoja na faili zilizobadilika na tofauti. Unaikubali, au unaacha maoni na timu inaamka na kujaribu tena. Wewe pekee ndiye unayeweza kuhamisha kadi hadi Zimekamilika.","Siku moja na AI-gile, kwa ufupi. Jioni unaacha maoni machache: kitufe hiki kiko mahali pasipofaa, orodha ile ipangwe, tunaweza kupata hali ya giza. Unaenda kulala. Mawakala wanasoma maoni, wanafanya mabadiliko, wanayajaribu na kukurudishia. Za kufanya zikiisha, mlinzi wa usiku anazijaza kutoka kwenye backlog kwa kadi zisizohitaji jibu lako. Asubuhi kuna rundo moja fupi: maswali machache na mambo kadhaa ya kujaribu, kila moja likiwa na hatua ambazo mtu mwenye usingizi anaweza kuzifuata na picha ya skrini inayoonyesha inafanya kazi. Unapitia, unakubali nzuri na kurudisha zilizobaki. Kihesabu cha tokeni kinaonyesha yote yalitumia kiasi gani, na No Token Mode ipo kwa wiki za kubana matumizi. Kisha unakula kifungua kinywa, ambapo mawakala bado hawawezi kusaidia. Wakati mwingine unaamka na swali la wakala aliyekwama, na unalijibu kwa sentensi moja kabla ya chai. Hakuna mkutano, hakuna barua pepe ndefu, hakuna kuuliza nani alibadilisha nini.","Kwanza, AI-gile si nini. Si kampuni changa, haiuzwi, na hakuna anayekusanya data yako. Ni ubao wa bure unaoendeshwa kwenye kompyuta yako, bila akaunti, bila vifuatiliaji na bila vidakuzi. Ni nini: mahali pamoja pa nadhifu pa kuona miradi yako yote ya AI ya kuandika msimbo kwa wakati mmoja, timu ya mawakala ikifanya kadi na wewe ukifanya maamuzi. Huunganisha kadi zinazohusiana, hurekebisha vichwa vilivyochanganyika, na hufuatilia jinsi msimbo unavyobaki mwepesi. Huzungumza takriban lugha 120, kuanzia Kiholanzi na Kiflemi hadi maharamia na Kiklingoni. Marafiki wanaweza kutumiana ujumbe, kwa faragha na kwa usimbaji. Ilijengwa na Rich na idadi kubwa ya mawakala wenye subira, hasa kwa kujitumia yenyewe. Iko kwenye pre-alpha iliyofungwa, kwa hiyo ina kasoro hapa na pale. Ukiona inavutia, omba kwa adabu na huenda ukaingia mapema."]}],"quips":{"1":"Neno moja. Jasiri. Labda jasiri kupita kiasi.","3":"Maneno matatu. Tayari ni ya kweli kuliko kurasa nyingi za bidhaa.","8":"Maneno manane. Bado ni mafupi kuliko stand-up.","21":"Kwa njia, urefu ni story points. Bila shaka ndivyo.","55":"Maneno hamsini na tano. Kadi mbili zimekamilika ulipokuwa unasoma hili.","144":"Hii ndiyo ndefu. Hakuna 233. Mawakala wamekwenda kulala."}},"timeline":{"first-idea.name":"Wazo la kwanza","first-idea.line":"Mazungumzo ya kwanza kabisa, kabla msimbo wowote haujakuwepo.","first-board.name":"Ubao wa kwanza","first-board.line":"Ubao unaofuatilia ujenzi wake wenyewe: kadi, safu, buruta na dondosha, miradi.","team-roles.name":"Timu na majukumu","team-roles.line":"Wasifu wa mawakala, violezo vya timu, nafasi na nani anafanya nini.","install.name":"Usakinishaji na matoleo","install.line":"Zip ambayo rafiki anaweza kusakinisha, kujisasisha, njia za matoleo na kurudi nyuma.","usage-saver.name":"Kiokoa matumizi","usage-saver.line":"Pima gharama za uendeshaji, weka msimbo mwepesi, okoa kikomo chako.","friends.name":"Marafiki na kushiriki","friends.line":"Ujumbe wa faragha, relay iliyosimbwa, mialiko, majukumu na miradi ya pamoja.","languages.name":"Lugha","languages.line":"Kila maandishi ya skrini kwenye faili la lugha, Kiholanzi na Kiflemi kwanza.","ai-tester.name":"Mjaribu wa AI","ai-tester.line":"Mjaribu hukagua kila makabidhiano kwanza na kuonyesha alichokiona.","website.name":"Tovuti","website.line":"aigile.lol, ukurasa wa utangulizi na ratiba hii.","streaming.name":"Gumzo na utiririshaji","streaming.line":"Discord, Twitch, OBS, hali ya mtiririshaji, GIF na emoji.","no-ai.name":"Toleo bila AI","no-ai.line":"Ubao kwa watu wanaoandika msimbo bila AI, na mbao za umma.","night-watch.name":"Mlinzi wa usiku","night-watch.line":"Mlinzi na Scrum Master huweka timu kwenye kazi ukiwa umelala.","p-more.name":"Mengine yote","p-more.line":"Mawazo madogo yanayosubiri zamu yake.","p-android.name":"Simu na Android","p-android.line":"Fikia ubao wako kutoka kwenye simu, kisha programu asilia ya Android.","p-release.name":"Alpha na zaidi","p-release.line":"Alpha iliyofungwa, tovuti hai, kisha beta.","p-languages.name":"Lugha zaidi","p-languages.line":"Zaidi ya lugha mia moja, na hali ya kuzama kwa wanaojifunza.","p-engines.name":"Injini zaidi za AI","p-engines.line":"Chagua Claude, Codex au Gemini kwa kila wakala.","p-pro.name":"Mazoea ya kitaalamu","p-pro.line":"Lebo za hatari, milango ya kuunganisha, kadi za matukio na vizuizi vya usalama.","p-self.name":"Kukutunza wewe","p-self.line":"Hali ya uchovu, vikumbusho vya kujitunza na 4:20.","p-servers.name":"Seva na ukuaji","p-servers.line":"Mipangilio ya seva ya kimataifa, majukumu na kupanga ukuaji.","p-livestream.name":"Ziada za utiririshaji","p-livestream.line":"Gumzo la Twitch, emoji maalum na mwonekano wa umma wa moja kwa moja."}};
